import { cn } from "@/lib/utils"

type Medium = "web" | "slide"
type SlideTitleCopy = { heading: string; subheading?: string; eyebrow?: string }

export function SlideTitle({ copy, medium = "web" }: { copy: SlideTitleCopy; medium?: Medium }) {
  const slide = medium === "slide"
  return (
    <section data-slot="slide-title" data-medium={medium} className={cn("flex flex-col justify-center gap-8 bg-background text-foreground", slide ? "aspect-video w-full overflow-hidden px-24 py-20" : "px-6 py-20 md:px-12")}>
      {copy.eyebrow ? <p className="text-sm font-medium uppercase tracking-wide text-muted-foreground">{copy.eyebrow}</p> : null}
      <h1 className={cn("font-heading font-semibold tracking-tight", slide ? "text-7xl" : "text-4xl md:text-5xl")}>{copy.heading}</h1>
      {copy.subheading ? <p className={cn("max-w-3xl text-muted-foreground", slide ? "text-3xl" : "text-lg")}>{copy.subheading}</p> : null}
    </section>
  )
}
